"""The tallybook command line."""

import datetime
import os
import sys

from tallybook import __version__
from tallybook.cli.args import Command, Fail, HelpRequested, UsageError, parse_command_args, whole
from tallybook.errors import NotFoundError, TallybookError

PROG = "tallybook"


# --------------------------------------------------------------------------- context
class Context:
    def __init__(self, db, today_arg):
        self.db = db
        self._today = today_arg
        self.out = []
        self.err = []
        self._store = None
        self.exit = 0

    @property
    def today(self):
        if self._today is None:
            self._today = datetime.date.today()
        return self._today

    def print(self, text=""):
        self.out.append(text + "\n")

    def write(self, text):
        self.out.append(text)

    def store(self, require=True):
        if self._store is None:
            from tallybook.storage import Store
            if not os.path.exists(self.db) and not os.path.isdir(self.db):
                raise Fail("no such database: %s (run `tallybook init`)" % self.db)
            try:
                self._store = Store.open(self.db)
            except NotFoundError:
                raise Fail("no such database: %s (run `tallybook init`)" % self.db) from None
        if require:
            self._store._require()
        return self._store

    def close(self):
        if self._store is not None:
            self._store.close()
            self._store = None


# ------------------------------------------------------------------------- helpers
def _date(text, what="date"):
    from tallybook.dates import parse_date
    return parse_date(text)


def _opt_date(opts, name, default=None):
    v = opts.get(name)
    return _date(v) if v is not None else default


def _period(text):
    from tallybook.dates import Period
    return Period.parse(text)


def _month_of(d):
    from tallybook.dates import period_containing
    return period_containing(d, "month")


def _money(text):
    from tallybook.money import Money
    return Money.parse(text)


def _json(ctx, value):
    from tallybook.export import to_json
    ctx.write(to_json(value))


def _table(ctx, headers, rows, align=None):
    from tallybook.export import render_table
    ctx.write(render_table(headers, rows, align))


def _read_file(name):
    if name == "-":
        data = sys.stdin.buffer.read() if hasattr(sys.stdin, "buffer") else sys.stdin.read().encode("utf-8")
    else:
        try:
            with open(name, "rb") as fh:
                data = fh.read()
        except OSError as e:
            raise Fail("cannot read %s: %s" % (name, e.strerror or e)) from None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Fail("cannot read %s: not UTF-8 text" % ("standard input" if name == "-" else name)) from None


def _file_label(name):
    return "standard input" if name == "-" else name


def _read_journal(name):
    from tallybook.journal import JournalError, parse_journal
    text = _read_file(name)
    try:
        return parse_journal(text)
    except JournalError as e:
        raise Fail("%s: %s" % (_file_label(name), e.message)) from None


def parse_posting(text):
    from tallybook.model import Posting
    from tallybook.money import Money
    note = ""
    body = text
    if ";" in text:
        body, note = text.split(";", 1)
        note = note.strip()
    parts = body.split()
    if len(parts) == 1:
        return Posting(parts[0], None, note)
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note)
    raise Fail("invalid posting '%s': expected 'ACCOUNT [AMOUNT CURRENCY] [; note]'" % text)


def _build_tx(date, payee, opts):
    from tallybook.model import Transaction
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(date, payee, opts.get("--narration", ""), postings, tuple(opts.get("--tag", [])),
                       opts.get("--flag", "*"), None)


def _tx_dict(tx):
    from tallybook.export import transaction_to_dict
    return transaction_to_dict(tx)


def _money_dict(m):
    from tallybook.export import money_to_dict
    return money_to_dict(m)


def _list_transactions(ctx, txs, as_json):
    if as_json:
        _json(ctx, [_tx_dict(t) for t in txs])
        return
    if not txs:
        return
    rows = [[t.id if t.id is not None else "", t.date.isoformat(), t.flag, t.payee, t.narration,
             " ".join("#" + g for g in sorted(set(t.tags)))] for t in txs]
    _table(ctx, ["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def _account_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency,
            "opened": a.opened.isoformat() if a.opened else None,
            "closed": a.closed.isoformat() if a.closed else None, "note": a.note}


def _plural(n, word):
    return "%d %s" % (n, word)


# ------------------------------------------------------------------------ commands
def cmd_init(ctx, a, o):
    from tallybook.storage import LATEST_VERSION, Store
    if not os.path.exists(ctx.db) and not os.path.isdir(ctx.db):
        with Store.open(ctx.db, create=True) as s:
            ctx.print("created %s (version %d)" % (ctx.db, s.version))
        return
    with Store.open(ctx.db) as s:
        v = s.version
        if v < LATEST_VERSION:
            s.migrate()
            ctx.print("migrated %s from version %d to %d" % (ctx.db, v, s.version))
        else:
            ctx.print("%s is up to date (version %d)" % (ctx.db, v))


def cmd_db_version(ctx, a, o):
    ctx.print(str(ctx.store(require=False).version))


def cmd_db_migrate(ctx, a, o):
    s = ctx.store(require=False)
    applied = s.migrate()
    if not applied:
        ctx.print("database is up to date (version %d)" % s.version)
    for v in applied:
        ctx.print("applied version %d" % v)


def cmd_db_info(ctx, a, o):
    info = ctx.store().info()
    if o.get("--json"):
        _json(ctx, info)
        return
    for k in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.print("%s: %s" % (k, info[k]))


def cmd_db_check(ctx, a, o):
    problems = ctx.store().check()
    if not problems:
        ctx.print("ok")
        return
    for p in problems:
        ctx.print(p)
    ctx.exit = 1


def cmd_db_backup(ctx, a, o):
    ctx.store().backup(a["DEST"])
    ctx.print("backed up to %s" % a["DEST"])


def cmd_serve(ctx, a, o):
    host = o.get("--host", "127.0.0.1")
    port = whole(o["--port"], "port", high=65535) if "--port" in o else 8765
    today = ctx._today
    ctx.store()
    ctx.close()
    from tallybook.api.server import serve
    flush_output(ctx)
    ctx.exit = serve(ctx.db, host=host, port=port, today=today) or 0


def cmd_account_add(ctx, a, o):
    opened = _opt_date(o, "--open")
    ctx.store().add_account(a["PATH"], currency=o.get("--currency"), opened=opened, note=o.get("--note", ""))
    ctx.print("added account %s" % a["PATH"])


def cmd_account_list(ctx, a, o):
    accounts = ctx.store().accounts(type=o.get("--type"), under=o.get("--under"), currency=o.get("--currency"),
                                    include_closed=not o.get("--open-only"))
    if o.get("--json"):
        _json(ctx, [_account_dict(x) for x in accounts])
        return
    if not accounts:
        return
    rows = [[x.path, x.type, x.currency or "", x.opened.isoformat() if x.opened else "",
             x.closed.isoformat() if x.closed else "", x.note] for x in accounts]
    _table(ctx, ["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows)


def cmd_account_show(ctx, a, o):
    s = ctx.store()
    acc = s.get_account(a["PATH"])
    ledger = s.ledger()
    bal = ledger.balance(acc.path)
    monies = [bal[c] for c in sorted(bal)]
    if o.get("--json"):
        d = _account_dict(acc)
        d["balance"] = [_money_dict(m) for m in monies]
        _json(ctx, d)
        return
    ctx.print("path: %s" % acc.path)
    ctx.print("type: %s" % acc.type)
    ctx.print("currency: %s" % (acc.currency or "any"))
    ctx.print("opened: %s" % (acc.opened.isoformat() if acc.opened else "none"))
    ctx.print("closed: %s" % (acc.closed.isoformat() if acc.closed else "none"))
    ctx.print(("note: %s" % acc.note) if acc.note else "note:")
    ctx.print("balance: %s" % (", ".join(str(m) for m in monies) if monies else "none"))


def cmd_account_close(ctx, a, o):
    on = _opt_date(o, "--on") or ctx.today
    ctx.store().close_account(a["PATH"], on)
    ctx.print("closed account %s on %s" % (a["PATH"], on.isoformat()))


def cmd_tx_add(ctx, a, o):
    date = _opt_date(o, "--date") or ctx.today
    tx = _build_tx(date, a["PAYEE"], o)
    stored = ctx.store().add_transaction(tx)
    if o.get("--json"):
        _json(ctx, _tx_dict(stored))
    else:
        ctx.print("added transaction %d" % stored.id)


def _paging(o):
    limit = whole(o["--limit"], "limit") if "--limit" in o else None
    offset = whole(o["--offset"], "offset") if "--offset" in o else 0
    return limit, offset


def cmd_tx_list(ctx, a, o):
    limit, offset = _paging(o)
    txs = ctx.store().transactions(query=o.get("--query"), limit=limit, offset=offset)
    _list_transactions(ctx, txs, o.get("--json"))


def cmd_tx_show(ctx, a, o):
    from tallybook.journal import format_transaction
    tid = whole(a["ID"], "transaction id", negative=True)
    tx = ctx.store().get_transaction(tid)
    if o.get("--json"):
        _json(ctx, _tx_dict(tx))
        return
    ctx.print("; id %d" % tx.id)
    ctx.write(format_transaction(tx))


def cmd_tx_delete(ctx, a, o):
    tid = whole(a["ID"], "transaction id", negative=True)
    ctx.store().delete_transaction(tid)
    ctx.print("deleted transaction %d" % tid)


def cmd_query(ctx, a, o):
    s = ctx.store()
    if o.get("--count"):
        ctx.print(str(s.count_transactions(a["QUERY"])))
        return
    limit, offset = _paging(o)
    txs = s.transactions(query=a["QUERY"], limit=limit, offset=offset)
    _list_transactions(ctx, txs, o.get("--json"))


def cmd_export(ctx, a, o):
    from tallybook.export import transactions_to_csv, transactions_to_json
    from tallybook.journal import format_journal
    fmt = o.get("--format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise Fail("unknown export format '%s': expected csv, json or journal" % fmt)
    if fmt == "journal":
        if "--query" in o:
            raise Fail("--query cannot be used with --format journal")
        ctx.write(format_journal(ctx.store().journal()))
        return
    txs = ctx.store().transactions(query=o.get("--query"))
    ctx.write(transactions_to_csv(txs) if fmt == "csv" else transactions_to_json(txs))


def cmd_journal_export(ctx, a, o):
    from tallybook.journal import format_journal
    ctx.write(format_journal(ctx.store().journal()))


def cmd_journal_import(ctx, a, o):
    journal = _read_journal(a["FILE"])
    ctx.store().load_journal(journal)
    ctx.print("imported %s, %s, %s" % (_plural(len(journal.accounts), "accounts"),
                                       _plural(len(journal.rates), "rates"),
                                       _plural(len(journal.transactions), "transactions")))


def _row_errors(errors):
    first = "%d rows could not be imported" % len(errors)
    return first, ["row %d: %s" % (n, m) for n, m in errors]


def cmd_import(ctx, a, o):
    has_name = "--profile" in o
    has_file = "--profile-file" in o
    if has_name == has_file:
        raise UsageError("give exactly one of --profile and --profile-file")
    from tallybook.csvimport import parse_profile
    if has_file:
        profile = parse_profile(_read_file(o["--profile-file"]))
    else:
        profile = o["--profile"]
    text = _read_file(a["FILE"])
    s = ctx.store()
    if not has_file:
        profile = parse_profile(s.profile_text(profile))
    outcome = s.import_csv(text, profile, apply_rules=not o.get("--no-rules"))
    if outcome.errors:
        first, lines = _row_errors(outcome.errors)
        raise Fail(first + ", nothing was imported", extra=lines)
    ctx.print("imported %s, %s" % (_plural(len(outcome.added), "transactions"),
                                   _plural(len(outcome.duplicates), "duplicates")))


def cmd_profile_add(ctx, a, o):
    text = _read_file(a["FILE"])
    ctx.store().set_profile(a["NAME"], text)
    ctx.print("stored profile %s" % a["NAME"])


def cmd_profile_list(ctx, a, o):
    names = ctx.store().profiles()
    if o.get("--json"):
        _json(ctx, names)
        return
    for n in names:
        ctx.print(n)


def cmd_profile_show(ctx, a, o):
    text = ctx.store().profile_text(a["NAME"])
    if text and not text.endswith("\n"):
        text += "\n"
    ctx.write(text)


def cmd_profile_remove(ctx, a, o):
    ctx.store().remove_profile(a["NAME"])
    ctx.print("removed profile %s" % a["NAME"])


def cmd_rules_set(ctx, a, o):
    from tallybook.rules import parse_rules
    text = _read_file(a["FILE"])
    n = len(parse_rules(text))
    ctx.store().set_rules(text)
    ctx.print("stored %s" % _plural(n, "rules"))


def cmd_rules_show(ctx, a, o):
    text = ctx.store().rules_text()
    if text and not text.endswith("\n"):
        text += "\n"
    ctx.write(text)


def cmd_rate_set(ctx, a, o):
    on = _opt_date(o, "--on") or ctx.today
    ctx.store().set_rate(a["FROM"], a["TO"], a["RATE"], on)
    ctx.print("set 1 %s = %s %s on %s" % (a["FROM"], a["RATE"], a["TO"], on.isoformat()))


def cmd_rate_list(ctx, a, o):
    rows = ctx.store().rate_rows()
    if o.get("--json"):
        _json(ctx, [{"from": s, "to": d, "date": on.isoformat(), "rate": t} for s, d, on, t in rows])
        return
    if rows:
        _table(ctx, ["From", "To", "Date", "Rate"], [[s, d, on.isoformat(), t] for s, d, on, t in rows], "lllr")


def cmd_rate_remove(ctx, a, o):
    on = _opt_date(o, "--on") or ctx.today
    ctx.store().remove_rate(a["FROM"], a["TO"], on)
    ctx.print("removed rate %s -> %s on %s" % (a["FROM"], a["TO"], on.isoformat()))


def _kind(o):
    kind = o.get("--per", "month")
    if kind not in ("month", "quarter", "year"):
        raise Fail("invalid period kind '%s': expected month, quarter or year" % kind)
    return kind


def cmd_budget_add(ctx, a, o):
    from tallybook.budgets import Budget
    kind = _kind(o)
    amount = _money(a["AMOUNT"])
    start = _opt_date(o, "--start") or ctx.today
    b = Budget(a["PATTERN"], kind, amount, start)
    ctx.store().add_budget(b)
    ctx.print("added budget %s %s per %s" % (b.pattern, b.amount, b.period_kind))


def cmd_budget_list(ctx, a, o):
    budgets = ctx.store().budgets()
    if o.get("--json"):
        _json(ctx, [{"pattern": b.pattern, "period_kind": b.period_kind, "amount": _money_dict(b.amount),
                     "start": b.start.isoformat()} for b in budgets])
        return
    if budgets:
        _table(ctx, ["Pattern", "Per", "Amount", "Start"],
               [[b.pattern, b.period_kind, str(b.amount), b.start.isoformat()] for b in budgets], "llrl")


def cmd_budget_remove(ctx, a, o):
    kind = _kind(o)
    ctx.store().remove_budget(a["PATTERN"], kind)
    ctx.print("removed budget %s per %s" % (a["PATTERN"], kind))


def _print_budget_lines(ctx, lines, as_json):
    if as_json:
        _json(ctx, [line.to_dict() for line in lines])
        return
    if not lines:
        return
    rows = [[l.pattern, l.period_kind, str(l.budget), str(l.actual), str(l.remaining), "%s%%" % l.percent,
             "over" if l.over else ""] for l in lines]
    _table(ctx, ["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"], rows, "llrrrrl")


def cmd_budget_status(ctx, a, o):
    from tallybook.budgets import budget_status
    period = _period(o["--period"]) if "--period" in o else _month_of(ctx.today)
    s = ctx.store()
    lines = budget_status(s.budgets(), s.ledger(), period)
    _print_budget_lines(ctx, lines, o.get("--json"))


def cmd_recurring_add(ctx, a, o):
    from tallybook.recurring import Recurring
    start = _opt_date(o, "--start") or ctx.today
    end = _opt_date(o, "--end")
    count = whole(o["--count"], "count", negative=True) if "--count" in o else None
    tmpl = _build_tx(start, a["PAYEE"], o)
    rec = Recurring(a["NAME"], a["SCHEDULE"], tmpl, start, end, count)
    ctx.store().add_recurring(rec)
    ctx.print("added recurring %s" % rec.name)


def cmd_recurring_list(ctx, a, o):
    s = ctx.store()
    items = s.recurring()
    through = {r.name: s.materialized_through(r.name) for r in items}
    if o.get("--json"):
        out = []
        for r in items:
            t = r.template
            out.append({"name": r.name, "schedule": str(r.schedule), "start": r.start.isoformat(),
                        "end": r.end.isoformat() if r.end else None, "count": r.count,
                        "materialized_through": through[r.name].isoformat() if through[r.name] else None,
                        "template": {"payee": t.payee, "narration": t.narration, "flag": t.flag,
                                     "tags": sorted(set(t.tags)),
                                     "postings": [{"account": p.account, "amount": _money_dict(p.amount),
                                                   "note": p.note} for p in t.postings]}})
        _json(ctx, out)
        return
    if not items:
        return
    rows = [[r.name, str(r.schedule), r.start.isoformat(), r.end.isoformat() if r.end else "",
             r.count if r.count is not None else "",
             through[r.name].isoformat() if through[r.name] else "", r.template.payee] for r in items]
    _table(ctx, ["Name", "Schedule", "Start", "End", "Count", "Through", "Payee"], rows)


def cmd_recurring_remove(ctx, a, o):
    ctx.store().remove_recurring(a["NAME"])
    ctx.print("removed recurring %s" % a["NAME"])


def cmd_recurring_materialize(ctx, a, o):
    upto = _opt_date(o, "--upto")
    made = ctx.store().materialize(upto=upto, today=ctx.today)
    if o.get("--json"):
        _json(ctx, [_tx_dict(t) for t in made])
    else:
        ctx.print("created %s" % _plural(len(made), "transactions"))


# ------------------------------------------------------------------------- reports
REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def _run_report(ctx, kind, ledger, account, o):
    from tallybook import reports
    if kind == "trial-balance":
        rep = reports.trial_balance(ledger, _opt_date(o, "--as-of"))
    elif kind == "balance-sheet":
        as_of = _opt_date(o, "--as-of") or ctx.today
        rep = reports.balance_sheet(ledger, as_of, convert_to=o.get("--convert"), today=ctx.today)
    elif kind == "income-statement":
        period = _period(o["--period"]) if "--period" in o else _month_of(ctx.today)
        rep = reports.income_statement(ledger, period, convert_to=o.get("--convert"))
    elif kind == "cashflow":
        period = _period(o["--period"]) if "--period" in o else _month_of(ctx.today)
        rep = reports.cashflow(ledger, period)
    else:
        period = _period(o["--period"]) if "--period" in o else None
        rep = reports.register(ledger, account, period, rollup=bool(o.get("--rollup")))
    if o.get("--json"):
        _json(ctx, rep)
    else:
        ctx.write(reports.render_text(rep))


def _report_handler(kind):
    def handler(ctx, a, o):
        _check_report_values(kind, o)
        _run_report(ctx, kind, ctx.store().ledger(), a.get("ACCOUNT"), o)
    return handler


def _check_report_values(kind, o):
    # read values before touching the book
    if "--as-of" in o and kind in ("trial-balance", "balance-sheet"):
        _date(o["--as-of"])
    if "--period" in o and kind != "trial-balance" and kind != "balance-sheet":
        _period(o["--period"])


# ---------------------------------------------------------------------------- calc
def cmd_calc_money_parse(ctx, a, o):
    m = _money(a["MONEY"])
    ctx.print("%d %s" % (m.minor, m.currency))


def cmd_calc_money_format(ctx, a, o):
    from tallybook.money import Money
    minor = whole(a["MINOR"], "minor units", negative=True)
    ctx.print(str(Money(minor, a["CUR"])))


def cmd_calc_money_add(ctx, a, o):
    ctx.print(str(_money(a["A"]) + _money(a["B"])))


def cmd_calc_money_sub(ctx, a, o):
    ctx.print(str(_money(a["A"]) - _money(a["B"])))


def cmd_calc_money_scale(ctx, a, o):
    m = _money(a["MONEY"])
    ratio = a["RATIO"]
    if "/" in ratio:
        n, d = ratio.split("/", 1)
    else:
        n, d = ratio, "1"
    num = whole(n, "ratio", negative=True)
    den = whole(d, "ratio", negative=True)
    if den == 0:
        raise Fail("invalid ratio '%s': the denominator is zero" % ratio)
    ctx.print(str(m.scale(num, den)))


def cmd_calc_money_allocate(ctx, a, o):
    m = _money(a["MONEY"])
    weights = [whole(w, "weight", negative=True) for w in a["WEIGHT"]]
    for part in m.allocate(weights):
        ctx.print(str(part))


def cmd_calc_money_convert(ctx, a, o):
    from tallybook.currency import RateTable, currency
    m = _money(a["MONEY"])
    currency(a["TO"])
    if a["TO"] == m.currency:
        raise Fail("cannot convert %s to itself" % m.currency)
    table = RateTable()
    on = datetime.date(2000, 1, 1)
    table.set(m.currency, a["TO"], a["RATE"], on)
    ctx.print(str(table.convert(m, a["TO"], on)))


WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


def cmd_calc_date_parse(ctx, a, o):
    d = _date(a["DATE"])
    ctx.print("%s %s" % (d.isoformat(), WEEKDAYS[d.weekday()]))


def cmd_calc_date_add_months(ctx, a, o):
    from tallybook.dates import add_months, format_date
    d = _date(a["DATE"])
    n = whole(a["N"], "number of months", negative=True)
    ctx.print(format_date(add_months(d, n)))


def cmd_calc_date_period(ctx, a, o):
    from tallybook.dates import format_date
    p = _period(a["PERIOD"])
    nxt = p.next()
    ctx.print("start: %s" % format_date(p.start))
    ctx.print("end: %s" % format_date(p.end))
    ctx.print("days: %d" % p.days)
    ctx.print("label: %s" % p.label)
    ctx.print("next: %s" % nxt.label)


def cmd_calc_date_periods(ctx, a, o):
    from tallybook.dates import DateError, periods
    start = _date(a["START"])
    end = _date(a["END"])
    step = a["STEP"]
    if step not in ("week", "month", "quarter", "year"):
        raise DateError("unknown step '%s': expected week, month, quarter or year" % step)
    if end >= start:
        days = (end - start).days
        months = (end.year - start.year) * 12 + end.month - start.month
        estimate = {"week": days // 7, "month": months, "quarter": months // 3, "year": end.year - start.year}[step]
        if estimate > 5002:
            raise Fail("too many periods: more than 5000")
    result = periods(start, end, step)
    if len(result) > 5000:
        raise Fail("too many periods: %d, more than 5000" % len(result))
    for p in result:
        ctx.print(p.label)


def cmd_calc_schedule(ctx, a, o):
    from tallybook.model import Posting, Transaction
    from tallybook.recurring import Recurring, occurrences, parse_schedule
    sched = parse_schedule(a["SCHEDULE"])
    frm = _date(o["--from"])
    to = _date(o["--to"])
    start = _opt_date(o, "--start") or frm
    end = _opt_date(o, "--end")
    count = whole(o["--count"], "count", negative=True) if "--count" in o else None
    tmpl = Transaction(start, "x", "", [], (), "*", None)
    rec = Recurring("calc", sched, tmpl, start, end, count)
    if (to - min(frm, start)).days > 40000:
        raise Fail("the window is too long: more than 40000 days")
    if to < frm:
        return
    for d in occurrences(rec, frm, to):
        ctx.print(d.isoformat())


